      "يربط طريق الحرير القديم الصين تجارياً بالعالم، بينما تهدف مبادرة 'الحزام والطريق' الحديثة لتعزيز الروابط الاقتصادية وتواجه تحديات الديون والمنافسة الدولية.",
      "برع الصينيون في العلوم والطب (الوخز بالإبر) والرياضيات والفلك والعمارة المعتمدة على الخشب والآجر."
