    "summary": "بدأ نظام الخلافة بعد وفاة الرسول ﷺ بالاعتماد على الشورى والبيعة بشقيها الخاص والعام لاختيار الخليفة الأنسب لإدارة شؤون المسلمين، ثم تطور تاريخياً ليتحول في العصر الأموي إلى التعيين بالوراثة، وهو ما استمر في العصرين العباسي والعثماني. ولم تكن شروط ولاية العهد محددة بنصوص شرعية بل خضعت للاجتهاد لتحقيق مصلحة الأمة، مع التركيز على صفات الرشد، والتقوى، والخبرة العسكرية والسياسية. وتزامن مع هذا التطور نشوء منصب الوزارة لمساعدة الخليفة؛ حيث ظهر رسمياً لأول مرة في العصر العباسي وتقلده أبو سلمة الخلال، بينما لُقب رئيس الوزراء في الدولة العثمانية بالصدر الأعظم. وفي الجانب الإداري، عُين الولاة لإدارة الأمصار وفق معايير الكفاءة، وقسمت الإمارات إلى خاصة وعامة (استكفاء واستيلاء)، حيث ظهرت إمارة الاستيلاء نتيجة ضعف السلطة المركزية ونشوء دول مستقلة كالدولة الطولونية.\n\nونظراً لاتساع رقعة الدولة العربية الإسلامية، قُسمت إلى ولايات ووحدات إدارية لتسهيل إدارتها، واستحدثت الدواوين كأجهزة إدارية ومالية متطورة. وتعددت مهام هذه الدواوين لتشمل ديوان الجند لتسجيل المقاتلين ورواتبهم، وديوان الخراج لجباية ضرائب الأراضي، وديوان البريد لنقل الرسائل ومراقبة الولاة، وديوان العطاء لتوزيع الغنائم، وديوان المظالم للنظر في الشكاوى، وديوان الإنشاء للرسائل الرسمية. وفي عهد الخليفة الأموي عبد الملك بن مروان، اتُّخذ قرار تاريخي بتعريب الدواوين وتحويل لغتها من الفارسية واليونانية والقبطية إلى العربية، مما أدى إلى تنسيق أفضل بين الولايات، وتعزيز قوة الدولة المركزية، وتوسيع نطاق التأثير الثقافي والسياسي للغة العربية.",
