    "summary": "شهد القرن العشرون تصاعداً لحركات التحرر الوطني في بلاد الشام لمواجهة الاستعمارين الفرنسي والبريطاني. ففي سوريا ولبنان، فرضت فرنسا انتدابها بعد معركة ميسلون عام 1920م وقسمت البلاد لدويلات وحاربت الثقافة العربية، مما أدى لاندلاع الثورة السورية الكبرى عام 1925م بقيادة سلطان باشا الأطرش، والتي حظيت بدعم أردني كبير بالمال والسلاح حتى نالت سوريا ولبنان استقلالهما في أربعينيات القرن الماضي. وفي الأردن، قاد الأمير عبد الله بن الحسين الجهود الدبلوماسية والشعبية لمقاومة الانتداب البريطاني ورفض معاهدة 1928م المقيدة للحريات، وتوجت هذه الجهود بإلغاء المعاهدة وإعلان استقلال المملكة الأردنية الهاشمية التام في 25 أيار 1946م ومبايعته ملكاً على البلاد.\n\nأما في العراق، فقد أدت السياسات البريطانية الجائرة واستغلال الثروات وتدهور الاقتصاد إلى اندلاع ثورة العشرين عام 1920م، والتي أجبرت بريطانيا على تغيير سياستها وتأسيس حكومة وطنية وتنصيب الملك فيصل بن الحسين ملكاً عام 1921م. تلا ذلك صراع مستمر وتطور للحركة الوطنية العراقية ضد المعاهدات البريطانية المقيدة مثل معاهدة بورتسموث، مروراً بعهد الملك غازي والملك فيصل الثاني، وصولاً إلى قيام الاتحاد العربي بين الأردن والعراق عام 1958م، والذي انتهى في العام نفسه بقيام النظام الجمهوري إثر انقلاب عسكري، مما يظهر بوضوح دوافع الاستعمار الأوروبي في السيطرة على المقدرات العربية ويبرز مكانة الهاشميين التاريخية في قيادة مشروع التحرر.",
